sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    // current = sysapproval_approver, get the grant program (sysapproval field)
    var grantProgram = current.sysapproval; 
    if (grantProgram) {
        var instanceUrl = gs.getProperty('glide.servlet.uri');
        var grantSysId = grantProgram.sys_id.toString();
        var grantUrl = instanceUrl + 'x/enno/gatenow-workspace/my-record-page-2/x_enno_gatenow_grant_program/' + grantSysId;
        template.print(grantUrl);
    } else {
        template.print('#'); // fallback
    }
})(current, template, email, email_action, event);
